# ----------------------------------------------------------------------------------------------
def _new_run(query: Query, context: ContextSnapshot | None) -> dict:  
    limit = 300.0  
    if context is not None:  
        limit = float(context.time_budget.limit_seconds)  
    start = time.monotonic()  
    end = start + max(45.0, limit - max(25.0, limit * 0.09))  
    reserve = max(70.0, min(105.0, limit * 0.35))  
    return {"start": start, "end": end, "research_end": end - reserve, "sources": [], "url_source": {},  
            "searches": 0, "fetches": 0, "read": {}, "fast": bool(query.fast), "schema": query.output_schema,  
            "models": list(DRIVER_MODELS), "trace": []}
def _mark(run: dict, text: str) -> None:  
    if DEBUG_TRACE:  
        run["trace"].append(f"{time.monotonic() - run['start']:.0f}s {text}")
def _left(run: dict, key: str = "end") -> float:  
    return run[key] - time.monotonic()
def _terms(text: str) -> list:  
    out = []  
    for w in re.findall(r"[A-Za-z0-9][A-Za-z0-9.\-/]{2,}", text.lower()):  
        w = w.strip(".")  
        if len(w) > 2 and w not in _STOP and w not in out:  
            out.append(w)  
    return out[:60]
def _add_source(run: dict, receipt_id: str, result, kind: str) -> int | None:  
    text = getattr(result, "note", None) or ""  
    if len(text.strip()) < 30:  
        return None  
    run["sources"].append({"receipt_id": receipt_id, "result_id": result.result_id, "kind": kind,  
                           "url": getattr(result, "url", None) or "", "title": getattr(result, "title", None) or "",  
                           "text": text})  
    return len(run["sources"])

# ----------------------------------------------------------------------------------------------
def _source(run: dict, number) -> dict | None:  
    try:  
        n = int(number)  
    except (TypeError, ValueError):  
        return None  
    if 1 <= n <= len(run["sources"]):  
        return run["sources"][n - 1]  
    return None
def _note_read(run: dict, n: int, start: int, end: int) -> None:  
    run["read"].setdefault(n, []).append((start, end))


