# ----------------------------------------------------------------------------------------------
def _windows(text: str, terms: list, count: int, size: int, skip_until: int) -> list:  
    """Best `count` windows of `size` characters after skip_until, by term density."""  
    if len(text) <= skip_until:  
        return []  
    low = text.lower()  
    marks = []  
    for t in terms:  
        start = 0  
        hits = 0  
        while hits < 80:  
            i = low.find(t, start)  
            if i == -1:  
                break  
            if i >= skip_until:  
                marks.append(i)  
            start = i + len(t)  
            hits += 1  
    if not marks:  
        return []  
    marks.sort()  
    best = []  
    for m in marks:  
        lo = max(skip_until, m - size // 3)  
        hi = min(len(text), lo + size)  
        score = sum(1 for x in marks if lo <= x < hi)  
        best.append((score, lo, hi))  
    best.sort(reverse=True)  
    chosen = []  
    for _score, lo, hi in best:  
        if all(hi <= a or lo >= b for a, b in chosen):  
            chosen.append((lo, hi))  
        if len(chosen) >= count:  
            break  
    return sorted(chosen)

