async def _tool_search(run: dict, args: dict) -> str:  
    q = str(args.get("query") or "").strip()[:400]  
    if not q:  
        return "error: empty query"  
    if run["searches"] >= MAX_SEARCHES:  
        return "search budget used up: work with the sources you have"  
    run["searches"] += 1  
    for provider in SEARCH_PROVIDERS:  
        try:  
            resp = await search_web(q, provider=provider, num=SEARCH_NUM, timeout=SEARCH_TIMEOUT)  
        except Exception:  
            continue  
        lines = []  
        for r in resp.results:  
            n = _add_source(run, resp.receipt_id, r, "search")  
            if n:  
                excerpt = re.sub(r"\s+", " ", run["sources"][n - 1]["text"])[:SEARCH_EXCERPT]  
                lines.append(f"[{n}] {run['sources'][n - 1]['title'][:120]} <{run['sources'][n - 1]['url']}>\n"  
                             f"    {excerpt}")  
        return "\n".join(lines) or "no results"  
    return "search failed"

