async def _tool_fetch(run: dict, args: dict, question: str) -> str:  
    url = str(args.get("url") or "").strip()  
    if not url.startswith("http"):  
        return "error: give a full http(s) url"  
    if url in run["url_source"]:  
        n = run["url_source"][url]  
        return (f"already fetched as [{n}] ({len(run['sources'][n - 1]['text'])} chars). Use find_in_source / "  
                f"read_source on [{n}].")  
    if run["fetches"] >= MAX_FETCHES:  
        return "fetch budget used up: work with the sources you have"  
    run["fetches"] += 1  
    for provider in FETCH_PROVIDERS:  
        extra = {"full_content": True} if provider == "parallel" else None  
        try:  
            resp = await fetch_page(url, provider=provider, provider_extra=extra, timeout=FETCH_TIMEOUT)  
        except Exception:  
            continue  
        best = None  
        for r in resp.results:  
            n = _add_source(run, resp.receipt_id, r, "page")  
            if n and (best is None or len(run["sources"][n - 1]["text"]) > len(run["sources"][best - 1]["text"])):  
                best = n  
        if best is None:  
            continue  
        run["url_source"][url] = best  
        src = run["sources"][best - 1]  
        text = src["text"]  
        parts = [f"[{best}] {src['title'][:120]} <{url}> total {len(text)} chars\n--- opening ---\n"  
                 f"{text[:FETCH_HEAD]}"]  
        _note_read(run, best, 0, min(len(text), FETCH_HEAD))  
        for lo, hi in _windows(text, _terms(question), FETCH_WINDOWS, FETCH_WINDOW, FETCH_HEAD):  
            parts.append(f"--- offset {lo} ---\n{text[lo:hi]}")  
            _note_read(run, best, lo, hi)  
        if len(text) > FETCH_HEAD:  
            parts.append(f"(showing part of {len(text)} chars; use find_in_source/read_source on [{best}])")  

# ----------------------------------------------------------------------------------------------
        return "\n".join(parts)  
    return "fetch failed for that url; try another source"
def _tool_find(run: dict, args: dict) -> str:  
    src = _source(run, args.get("source"))  
    needle = str(args.get("text") or "").strip().lower()  
    if src is None or not needle:  
        return "error: unknown source number or empty text"  
    low = src["text"].lower()  
    out = []  
    start = 0  
    while len(out) < FIND_HITS:  
        i = low.find(needle, start)  
        if i == -1:  
            break  
        lo, hi = max(0, i - FIND_CONTEXT), min(len(low), i + len(needle) + FIND_CONTEXT)  
        out.append(f"@{i}: ...{re.sub(chr(10), ' | ', src['text'][lo:hi])}...")  
        start = i + len(needle)  
    total = low.count(needle)  
    head = f"{total} match(es) in [{args.get('source')}] ({len(low)} chars)"  
    return head + ("\n" + "\n".join(out) if out else "")
def _tool_read(run: dict, args: dict) -> str:  
    src = _source(run, args.get("source"))  
    if src is None:  
        return "error: unknown source number"  
    try:  
        offset = max(0, int(args.get("offset") or 0))  
        length = min(READ_MAX, max(200, int(args.get("length") or READ_MAX)))  
    except (TypeError, ValueError):  
        return "error: offset/length must be integers"  
    text = src["text"]  
    if offset >= len(text):  
        return f"offset beyond end ({len(text)} chars)"  
    end = min(len(text), offset + length)  
    _note_read(run, int(args.get("source")), offset, end)  
    return f"[{args.get('source')}] chars {offset}-{end} of {len(text)}\n{text[offset:end]}"
def _run_code(code: str) -> object:  
    return safe_exec(code, {})

# ----------------------------------------------------------------------------------------------
def _tool_compute(args: dict) -> str:  
    code = str(args.get("code") or "")  
    if not code.strip():  
        return "error: empty code"  
    if re.search(r"\bwhile\s+True\b|\binput\(|\bopen\(|\bsocket\b|\bsubprocess\b|\bimport\s+os\b", code):  
        return "error: only pure computation is allowed"  
    try:  
        value = _run_code(code)  
        return json.dumps(value, default=str)[:4000]  
    except Exception as exc:  
        return f"error: {str(exc)[:300] or 'code raised an exception'}"
async def _run_tool(run: dict, name: str, args: dict, question: str) -> str:  
    try:  
        if name == "search_web":  
            return await _tool_search(run, args)  
        if name == "fetch_page":  
            return await _tool_fetch(run, args, question)  
        if name == "find_in_source":  
            return _tool_find(run, args)  
        if name == "read_source":  
            return _tool_read(run, args)  
        if name == "compute":  
            return _tool_compute(args)  
    except Exception as exc:  
        return f"tool error: {str(exc)[:200]}"  
    return f"unknown tool {name}"


